        ['rect', { x: 22, y: 5, width: 20, height: 2, rx: 1, opacity: 0.6 }],
        ['ellipse', { cx: 32, cy: 34, rx: 3.4, ry: 26 }],
        ['polygon', { points: '5,24 59,24 59,30 5,30' }],
        ['polygon', { points: '21,53 43,53 43,57 21,57' }]
