  // A saved checkbox is a review record, not an aircraft inspection. Ignore
  // obsolete keys and malformed values so progress describes this reference.
  function normalizeFlightLearningSearch(value) {
    return String(value == null ? '' : value).normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
      .toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
  }

  function searchFlightLearningTopics(topics, query) {
    var normalized = normalizeFlightLearningSearch(String(query == null ? '' : query).slice(0, 200));
    var terms = normalized ? normalized.split(/\s+/) : [];
    var cardCount = 0;
    var searchableText = function(value, seen, depth) {
      if (typeof value === 'string' || typeof value === 'number') return String(value);
      if (!value || typeof value !== 'object' || depth > 8 || seen.indexOf(value) >= 0) return '';
      seen.push(value);
      var parts = Object.keys(value).filter(function(key) { return key !== 'icon'; })
        .map(function(key) { return searchableText(value[key], seen, depth + 1); });
      seen.pop();
      return parts.join(' ');
    };
    var results = (Array.isArray(topics) ? topics : []).map(function(topic) {
      var data = Array.isArray(topic.data) ? topic.data : [];
      var context = String(topic.label || '') + ' ' + String(topic.id || '');
      var entries = data.filter(function(entry) {
        if (!terms.length) return true;
        var text = normalizeFlightLearningSearch(context + ' ' + searchableText(entry, [], 0));
        return terms.every(function(term) { return text.indexOf(term) >= 0; });
      });
      cardCount += entries.length;
      return Object.assign({}, topic, { data: entries, totalCards: data.length });
    }).filter(function(topic) { return !terms.length || topic.data.length > 0; });
    return { topics: results, cardCount: cardCount, searching: terms.length > 0 };
  }

  function normalizePreflightChecks(saved) {
    var source = saved && typeof saved === 'object' && !Array.isArray(saved) ? saved : {};
    var checked = {};
    PREFLIGHT_CHECKLIST.forEach(function(phase) {
      phase.items.forEach(function(_, idx) {
        var key = phase.phase + '-' + idx;
        if (Object.prototype.hasOwnProperty.call(source, key) && source[key] === true) checked[key] = true;
      });
    });
    return checked;
  }

