      var geodeticToLocal = function(lat, lon, alt, referenceLon) {
        if (!originRef.current) {
          originRef.current = { lat: lat, lon: lon, alt: alt };
        }
        // Geographic targets use the aircraft's current longitude branch. Keep
        // player and terrain coordinates unwrapped so the world stays continuous.
        if (Number.isFinite(referenceLon)) lon = referenceLon + ((lon - referenceLon) % 360 + 540) % 360 - 180;
        var R = 364800.0;
        var cosLat = Math.max(0.000001, Math.cos(originRef.current.lat * Math.PI / 180));
        var x = (lon - originRef.current.lon) * R * cosLat;
        var y = alt;
        var z = -(lat - originRef.current.lat) * R;
        return { x: x, y: y, z: z };
      };

      // Night lights for real towns around the aircraft. Point count and spread
      // grow with population, and each town's pattern is seeded by its own
      // coordinates, so a city always glows the same way. Water stays dark.
      var buildFlightLightCarpet = function(carpet, state, tierScale) {
        var positions = carpet.geometry.attributes.position.array;
        var colors = carpet.geometry.attributes.color.array;
        var max = carpet.userData.max, count = 0;
        var lightLatLon = carpet.userData.lightLatLon || (carpet.userData.lightLatLon = new Float32Array(max * 2));
        var towns = nearestRealCities(state.lat, state.lon, 45);
        for (var ti = 0; ti < towns.length && count < max; ti++) {
          var town = towns[ti];
          var popK = Math.max(1, Number(town.popK) || 1);
          var townPoints = Math.max(4, Math.round(Math.max(10, Math.min(400, 25 * Math.sqrt(popK / 50))) * tierScale));
          var spreadNm = Math.min(8, 0.8 + 0.6 * Math.sqrt(popK / 100));
          var townElev = 0;
          try { townElev = groundBelowAircraft(town.lat, town.lon); } catch (e) {}
          if (!Number.isFinite(townElev)) townElev = 0;
          var seed = Math.floor(Math.abs(Math.sin(town.lat * 12.9898 + town.lon * 78.233)) * 233280);
          var next = function() { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
          var cosLat = Math.max(0.05, Math.cos(town.lat * Math.PI / 180));
          var distanceFade = Math.max(0.35, 1 - town.distNm / 60);
          for (var pi = 0; pi < townPoints && count < max; pi++) {
            var angle = next() * Math.PI * 2, radius = spreadNm * Math.pow(next(), 0.75);
            var white = next() < 0.3;
            var lightLat = town.lat + radius * Math.cos(angle) / 60;
            var lightLon = town.lon + radius * Math.sin(angle) / (60 * cosLat);
            if (isWaterMask(lightLat, lightLon)) continue;
            // One elevation per town keeps a rebuild cheap: a terrain lookup per
            // light (up to 6,000) stalled a frame. Lights sit just above the town.
            var spot = geodeticToLocal(lightLat, lightLon, townElev + 120, state.lon);
            positions[count * 3] = spot.x; positions[count * 3 + 1] = spot.y; positions[count * 3 + 2] = spot.z;
            lightLatLon[count * 2] = lightLat; lightLatLon[count * 2 + 1] = lightLon;
            // Sodium orange with some white LED, brightest at each town's core.
            var core = (1 - 0.5 * radius / spreadNm) * distanceFade;
            colors[count * 3] = (white ? 0.95 : 1) * core;
            colors[count * 3 + 1] = (white ? 0.95 : 0.72) * core;
            colors[count * 3 + 2] = (white ? 1 : 0.38) * core;
            count++;
          }
        }
        carpet.geometry.setDrawRange(0, count);
        carpet.geometry.attributes.position.needsUpdate = true;
        carpet.geometry.attributes.color.needsUpdate = true;
        carpet.userData.scan = { lat: state.lat, lon: state.lon, origin: originRef.current, tierScale: tierScale, count: count };
      };

