                      gfx.fillRect(sBx + sBw * 0.15, sBtopY - sBh * 0.18, sBw * 0.7, sBh * 0.18);
                      gfx.fillStyle = 'rgba(' + Math.round(rCol - 20) + ',' + Math.round(gCol - 20) + ',' + Math.round(bCol - 20) + ',' + sBbaseAlpha + ')';
