                  gfx.lineWidth = 1.2;
                  var hwx = cityStartX + cityWide * 0.5;
                  gfx.beginPath(); gfx.moveTo(hwx, y - elevBump); gfx.lineTo(hwx + (terrainHash(r, scanLat) - 0.5) * 40, y + rowH); gfx.stroke();
                  // Lane markings
                  gfx.strokeStyle = 'rgba(220,220,150,' + (0.3 * depth) + ')';
                  gfx.lineWidth = 0.3;
                  gfx.setLineDash([2, 3]);
                  gfx.beginPath(); gfx.moveTo(hwx, y - elevBump); gfx.lineTo(hwx + (terrainHash(r, scanLat) - 0.5) * 40, y + rowH); gfx.stroke();
