          if (!threeLoaded) {
            // World labels (continents/oceans at high altitude)
            drawWorldLabels(gfx, W, H, horizonY, state);
          }

          // Weather lesson display
          if (d.flightDetails && d.weatherLesson && timeRef.current < 10) {
            var wlAlpha = Math.min(1, (8 - timeRef.current) / 2);
            if (wlAlpha > 0) {
              var wlW = Math.min(W - 40, 380);
              var wlX = (W - wlW) / 2;
              var wlY = H * 0.75;
              gfx.globalAlpha = Math.max(0, wlAlpha);
              gfx.fillStyle = 'rgba(0,0,0,0.75)';
              gfx.beginPath(); gfx.roundRect(wlX, wlY, wlW, 40, 8); gfx.fill();
              gfx.strokeStyle = 'rgba(34,211,238,0.4)'; gfx.lineWidth = 1; gfx.stroke();
              gfx.fillStyle = '#22d3ee'; gfx.font = 'bold 9px system-ui'; gfx.textAlign = 'left';
              gfx.fillText(__alloT('stem.flightsim.hud_weather_briefing', "🌤️ WEATHER BRIEFING"), wlX + 10, wlY + 14);
              gfx.fillStyle = '#94a3b8'; gfx.font = '9px system-ui';
              // Word wrap the lesson
              var wWords = d.weatherLesson.split(' ');
              var wLine = ''; var wLineY = wlY + 28;
              wWords.forEach(function(word) {
                var test = wLine + (wLine ? ' ' : '') + word;
                if (gfx.measureText(test).width > wlW - 20) { gfx.fillText(wLine, wlX + 10, wLineY); wLine = word; wLineY += 11; }
                else wLine = test;
              });
              if (wLine) gfx.fillText(wLine, wlX + 10, wLineY);
              gfx.globalAlpha = 1;
            }
          }

          // Check & render achievements
          checkAchievements(state, timeRef.current, dt);
          drawAchievementPopup(gfx, W, H, timeRef.current);

          // Coastal rescue overlay (distress beacon, hover bar, success card)
          drawRescueOverlay(gfx, W, H, horizonY, state, timeRef.current);

          // Drone aerial survey overlay (battery, photo waypoints, capture ring)
          drawSurveyOverlay(gfx, W, H, horizonY, state, timeRef.current);

          // HyperJet Sprint HUD (drawn over everything)
          drawSprintHUD(gfx, W, H, state, timeRef.current);

          // Landing score
          drawLandingScore(gfx, W, H, state, timeRef.current);

          // Educational milestones
          checkMilestones(gfx, W, H, state, timeRef.current);
          drawBriefFlightNotice(gfx, W, H, state, timeRef.current, stallTasKts, !!radioPanel);

          // Flight log tracking
          var log = logRef.current;
          if (log.startTime === 0) { log.startTime = timeRef.current; log.lastLat = state.lat; log.lastLon = state.lon; }
          if (state.altitude > log.maxAlt) log.maxAlt = state.altitude;
          var trueAirspeedKts = state.speed * 0.5924838;
          if (trueAirspeedKts > log.maxSpeed) log.maxSpeed = trueAirspeedKts;
          var segDist = haversineNm(log.lastLat, log.lastLon, state.lat, state.lon);
          if (segDist > 0.01) { log.distance += segDist; log.lastLat = state.lat; log.lastLon = state.lon; }
          // Airport visit tracking
          var landedAirport = landingRef.current.scored && landingRef.current.touchdownAirportDistance <= 2 && WAYPOINTS.find(function(wp) { return wp.id === landingRef.current.touchdownAirportId; });
          if (landedAirport && state.onGround && log.airborneSeconds >= 10 && log.airports.indexOf(landedAirport.code) < 0) {
            log.airports.push(landedAirport.code);
            var visited = dataRef.current.visitedAirports || [];
            if (visited.indexOf(landedAirport.id) < 0) { upd('visitedAirports', visited.concat([landedAirport.id])); }
          }
          evaluateFlightChallenge(dt);

          // Flight time display. Sits ABOVE the first-person glareshield (a
          // 58px near-opaque bar drawn later in the frame used to paint clean
          // over y=H−8, hiding the log entirely in cockpit view), and in a
          // light color — the old 40% black was invisible on the dark panel.
          var ft = Math.round(timeRef.current - log.startTime);
          var logLineY = d.thirdPerson ? H - 16 : H - 64;
          // Held during onboarding. At t=0 every figure in it is zero — "Dist:
          // 0 nm | Max Alt: 76 ft" — so it was one more text zone competing for a
          // beginner's attention while saying nothing. It appears the moment the
          // takeoff card is dismissed, which is also when it starts to mean something.
          if (d.flightDetails && d.takeoffTutorialDismissed && !instruments.compact) {
            gfx.fillStyle = 'rgba(226,232,240,0.75)'; gfx.font = '9px system-ui'; gfx.textAlign = 'left';
            // x=96 clears the airspeed tape (x 30..85) in both views.
            gfx.fillText(__alloT('stem.flightsim.hud_flight_log', "Flight: {time}  |  Dist: {dist} nm  |  Max Alt: {alt} ft  |  Airports: {airports}").replace('{time}', Math.floor(ft / 60) + ':' + String(ft % 60).padStart(2, '0')).replace('{dist}', Math.round(log.distance)).replace('{alt}', Math.round(log.maxAlt).toLocaleString()).replace('{airports}', log.airports.length), 96, logLineY);
          }

          // ═══ VISUAL EFFECTS LAYER ═══

          // WCAG 2.3.1: Skip particle/animation effects if reduced motion preferred
          if (!threeLoaded && !skyReducedMotion.current) {
          // ── Speed lines (visual sense of velocity) ──
          if (kts > 150) {
            var speedAlpha = Math.min(0.25, (kts - 150) / 500);
            gfx.strokeStyle = 'rgba(200,220,255,' + speedAlpha + ')';
            gfx.lineWidth = 1;
            for (var sl = 0; sl < Math.min(20, kts / 30); sl++) {
              var slx = (sl * 97 + scrollAccumRef.current.px) % W;
              var sly = (sl * 61 + 20) % (H * 0.7) + H * 0.15;
              var slLen = 10 + kts * 0.05;
              gfx.beginPath(); gfx.moveTo(slx, sly); gfx.lineTo(slx - slLen, sly + slLen * 0.2); gfx.stroke();
            }
          }

          // ── Sonic boom visual (near/above Mach 1) ──
          if (kts > 600) {
            var machAlpha = Math.min(0.15, (kts - 600) / 400);
            var machRing = (timeRef.current * 200) % 200;
            gfx.strokeStyle = 'rgba(255,255,255,' + (machAlpha * (1 - machRing / 200)) + ')';
            gfx.lineWidth = 2;
            gfx.beginPath(); gfx.arc(W / 2, H * 0.5, machRing * 1.5, -0.5, 0.5); gfx.stroke();
          }

          // ── City lights at night ──
          if (dayNight.isNight) {
            GEO_PLACES.forEach(function(place) {
              if (place.type === 'landmark') return;
              var dist = haversineNm(state.lat, state.lon, place.lat, place.lon);
              var visRange = Math.max(100, state.altitude / 80);
              if (dist > visRange) return;
              var brg2 = bearing(state.lat, state.lon, place.lat, place.lon);
              var relBrg2 = ((brg2 - state.heading + 180 + 360) % 360) - 180;
              if (Math.abs(relBrg2) > 80) return;
              var sx2 = W / 2 + (relBrg2 / 80) * (W / 2);
              var depth2 = 1 - dist / visRange;
              var sy2 = horizonY + (H - horizonY) * (0.3 + depth2 * 0.5);
              // Warm city glow
              var glowSize = 3 + depth2 * 12;
              var cityGrad = gfx.createRadialGradient(sx2, sy2, 0, sx2, sy2, glowSize);
              cityGrad.addColorStop(0, 'rgba(255,200,100,0.6)');
              cityGrad.addColorStop(0.5, 'rgba(255,180,80,0.2)');
              cityGrad.addColorStop(1, 'rgba(255,150,50,0)');
              gfx.fillStyle = cityGrad;
              gfx.fillRect(sx2 - glowSize, sy2 - glowSize, glowSize * 2, glowSize * 2);
              // Twinkle dots
              if (depth2 > 0.3) {
                gfx.fillStyle = 'rgba(255,220,150,' + (0.3 + Math.sin(timeRef.current * 4 + dist) * 0.2) + ')';
                for (var dot = 0; dot < Math.floor(depth2 * 5); dot++) {
                  var dx2 = sx2 + (Math.sin(dot * 2.7) * glowSize * 0.6);
                  var dy2 = sy2 + (Math.cos(dot * 3.1) * glowSize * 0.4);
                  gfx.fillRect(dx2, dy2, 1.5, 1.5);
                }
              }
            });
          }

          // ── Fireworks over major cities at night ──
          // When flying over a city of >1M people at night, render periodic
          // colorful bursts above the city glow. Tiny detail but pumps a huge
          // amount of "life" into the world — students glance down and see a
          // party happening in the city below. Bigger cities fire more bursts.
          if (dayNight.isNight && state.altitude < 18000 && state.altitude > 800) {
            GEO_PLACES.forEach(function(place, pci) {
              if (place.type === 'landmark') return;
              var popStr = String(place.pop || '');
              if (popStr.indexOf('M') < 0) return;
              var popM = parseFloat(popStr);
              if (!(popM >= 1)) return;
              var fwDist = haversineNm(state.lat, state.lon, place.lat, place.lon);
              var fwVisRange = Math.max(30, state.altitude / 250);
              if (fwDist > fwVisRange) return;
              var fwBrg = bearing(state.lat, state.lon, place.lat, place.lon);
              var fwRel = ((fwBrg - state.heading + 180 + 360) % 360) - 180;
              if (Math.abs(fwRel) > 70) return;
              var fwDepth = 1 - fwDist / fwVisRange;
              var fwCx = W / 2 + (fwRel / 70) * (W / 2);
              var fwCy = horizonY + (H - horizonY) * (0.28 + fwDepth * 0.48);
              // Fire 1-3 bursts per city based on population. Each burst has its
              // own phase offset so they don't all pop at the same moment.
              var fwBurstN = Math.min(3, Math.floor(popM / 5) + 1);
              for (var fb = 0; fb < fwBurstN; fb++) {
                var fbSeed = pci * 17 + fb * 31;
                var fbPhase = ((timeRef.current * 0.55 + fbSeed * 0.23) % 5) / 5;
                if (fbPhase > 0.45) continue; // off between bursts
                var fbLocal = fbPhase / 0.45; // 0..1 across one burst
                var fbOffX = ((fbSeed * 7) % 50) - 25;
                var fbOffY = ((fbSeed * 11) % 24) - 22; // lifted slightly above glow
                var fbX = fwCx + fbOffX * Math.max(0.2, fwDepth);
                var fbY = fwCy + fbOffY * Math.max(0.2, fwDepth);
                var fbHue = (fbSeed * 37) % 360;
                var fbR = (4 + fbLocal * 16) * Math.max(0.4, fwDepth);
                var fbAlpha = Math.pow(1 - fbLocal, 1.4);
                // Radial starburst streaks
                gfx.strokeStyle = 'hsla(' + fbHue + ',92%,65%,' + fbAlpha + ')';
                gfx.lineWidth = 0.9;
                for (var fs = 0; fs < 12; fs++) {
                  var fa = (fs / 12) * Math.PI * 2;
                  gfx.beginPath();
                  gfx.moveTo(fbX + Math.cos(fa) * fbR * 0.25, fbY + Math.sin(fa) * fbR * 0.25);
                  gfx.lineTo(fbX + Math.cos(fa) * fbR, fbY + Math.sin(fa) * fbR);
                  gfx.stroke();
                }
                // Bright core flash
                var fbCore = gfx.createRadialGradient(fbX, fbY, 0, fbX, fbY, fbR * 0.5);
                fbCore.addColorStop(0, 'hsla(' + fbHue + ',95%,85%,' + (fbAlpha * 0.9) + ')');
                fbCore.addColorStop(1, 'hsla(' + fbHue + ',90%,60%,0)');
                gfx.fillStyle = fbCore;
                gfx.fillRect(fbX - fbR, fbY - fbR, fbR * 2, fbR * 2);
              }
            });
          }

          // ── Aurora Borealis (near poles at night) ──
          if (dayNight.isNight && Math.abs(state.lat) > 55 && state.altitude > 5000) {
            var auroraIntensity = Math.min(1, (Math.abs(state.lat) - 55) / 20);
            for (var ai = 0; ai < 6; ai++) {
              var ax = W * 0.15 + ai * W * 0.12;
              var ay = horizonY * 0.15 + Math.sin(timeRef.current * 0.3 + ai * 1.2) * 30;
              var aHeight = 60 + Math.sin(timeRef.current * 0.5 + ai * 0.8) * 30;
              var aGrad = gfx.createLinearGradient(ax, ay, ax, ay + aHeight);
              var green = ai % 2 === 0 ? [0, 255, 100] : [100, 200, 255];
              aGrad.addColorStop(0, 'rgba(' + green[0] + ',' + green[1] + ',' + green[2] + ',0)');
              aGrad.addColorStop(0.3, 'rgba(' + green[0] + ',' + green[1] + ',' + green[2] + ',' + (auroraIntensity * 0.15) + ')');
              aGrad.addColorStop(0.7, 'rgba(' + green[0] + ',' + green[1] + ',' + green[2] + ',' + (auroraIntensity * 0.25) + ')');
              aGrad.addColorStop(1, 'rgba(' + green[0] + ',' + green[1] + ',' + green[2] + ',0)');
              gfx.fillStyle = aGrad;
              var aWave = 15 + Math.sin(timeRef.current * 0.7 + ai) * 10;
              gfx.fillRect(ax - aWave, ay, aWave * 2, aHeight);
            }
          }

          // Engine exhaust & wingtip vortex particles
          drawParticles(gfx, W, H, state, ctrl, timeRef.current);
          } // end reduced motion block

          // Force diagram. Drawn HERE, at the end of the world pass, not up
          // with the rest of the HUD: the terrain, runway and ground-shadow
          // layers all paint after that point and used to bury the lower
          // third of the card.
          var displayedForces = currentAC.isHelicopter || currentAC.isDrone
            ? Object.assign({}, state.forces, { thrust: state.forces.forward || 0,
              drag: Number.isFinite(state.forces.forwardDrag) ? state.forces.forwardDrag : state.forces.drag }) : state.forces;
          drawForces(gfx, W - 112, 352, displayedForces, showForces);

          // Controls reference is rendered as accessible, scrollable DOM
          // over the frozen flight display rather than canvas-only text.

          // ── Engine ignition cough ──
          // For ~1.6 s after the engine first fires (throttle lifts off zero
          // on the ground), draw an exhaust smoke plume centered in the lower
          // third of the screen + a small "IGNITION" label. Gives the first-
          // time student a real "I just started the engine" moment.
          if (flightRef.current._ignitionTime) {
            var igAge = timeRef.current - flightRef.current._ignitionTime;
            if (igAge >= 0 && igAge < 1.6) {
              var igFade = Math.max(0, 1 - igAge / 1.6);
              // Exhaust smoke puff (only drawn in chase cam; first-person the
              // exhaust is behind the cowl and we fake it with engine rumble).
              if (d.thirdPerson && !threeLoaded) {
                for (var igp = 0; igp < 5; igp++) {
                  var igAgeP = igAge - igp * 0.08;
                  if (igAgeP < 0) continue;
                  var igRad = 6 + igAgeP * 40;
                  var igX = W / 2 + 36 + igAgeP * 14;
                  var igY = H * 0.6 + Math.sin(igAgeP * 3 + igp) * 3;
                  var igAlpha = igFade * 0.45 * Math.max(0, 1 - igAgeP / 1.0);
                  var igGrad = gfx.createRadialGradient(igX, igY, 0, igX, igY, igRad);
                  igGrad.addColorStop(0, 'rgba(60,60,65,' + igAlpha + ')');
                  igGrad.addColorStop(0.5, 'rgba(120,120,130,' + (igAlpha * 0.5) + ')');
                  igGrad.addColorStop(1, 'rgba(180,180,190,0)');
                  gfx.fillStyle = igGrad;
                  gfx.fillRect(igX - igRad, igY - igRad, igRad * 2, igRad * 2);
                }
              }
              // Ignition label (both views)
              gfx.save();
              gfx.globalAlpha = igFade;
              gfx.font = 'bold 14px monospace';
              var igLbl = '\u26A1 IGNITION — RPM SPOOLING UP';
              var igW = gfx.measureText(igLbl).width + 24;
              gfx.fillStyle = 'rgba(2,6,23,0.8)';
              gfx.beginPath(); gfx.roundRect((W - igW) / 2, H * 0.35 - 16, igW, 28, 5); gfx.fill();
              gfx.strokeStyle = '#fb923c'; gfx.lineWidth = 1.5;
              gfx.beginPath(); gfx.roundRect((W - igW) / 2, H * 0.35 - 16, igW, 28, 5); gfx.stroke();
              gfx.fillStyle = '#fed7aa';
              gfx.textAlign = 'center'; gfx.textBaseline = 'middle';
              gfx.fillText(igLbl, W / 2, H * 0.35 - 2);
              gfx.restore();
              // (Ignition camera shake moved to the TOP of the frame, right
              // after the DPR transform — a translate here at the end of the
              // frame, wrapped in save/restore with nothing drawn between,
              // shook nothing.)
            } else {
              // Age out the flag after the callout fades
              flightRef.current._ignitionTime = 0;
            }
          }

          // ── Takeoff coaching callouts ──
          // Approximate, flap-adjusted rotation cues for powered fixed-wing
          // aircraft. This model has no accelerate-stop/runway-length data and
          // therefore cannot calculate or announce a takeoff decision speed.
          // One-shot each: once a
          // callout has fired, the flag on flightRef.current stays true until
          // we're airborne + above 500 ft AGL, at which point we reset for the
          // next takeoff. The same pattern is used by _stallAnnounced.
          if (!pausedRef.current && !heliMode && !droneMode && Physics.MAX_THRUST > 0) {
            var vKts = state.speed * 0.5924838;
            var vAgl = state.altitude - (state.fieldElev || 0);
            var fl = flightRef.current;
            if (!fl._callouts) fl._callouts = { airspeed: 0, vr: 0, climb: 0 };
            // Reset when solidly airborne
            if (vAgl > 500 && !state.onGround) fl._callouts = { airspeed: 0, vr: 0, climb: 0 };
            // Per-aircraft speeds derived from the live stall speed (same rule
            // as the tape's Vr marker) — the old fixed 45/55 kts was Cessna-only.
            var _vrCallKts = Math.round(stallTasKts * 1.1);
            var _airspeedCueKts = Math.round(_vrCallKts * 0.82);
            var calloutMsg = null, calloutColor = '#38bdf8';
            var groundTakeoffIntent = state.onGround && ctrl.throttle >= 0.5 && !ctrl.brake;
            if (groundTakeoffIntent && vKts >= _airspeedCueKts && vKts < _vrCallKts && !fl._callouts.airspeed) {
              calloutMsg = __alloT('stem.flightsim.hud_airspeed_building', 'AIRSPEED BUILDING');
              fl._callouts.airspeed = timeRef.current;
              if (typeof skyAnnounce === 'function') skyAnnounce(__alloT('stem.flightsim.announce_airspeed_building', 'Airspeed building. Continue monitoring the rotation cue.'));
            } else if (groundTakeoffIntent && vKts >= _vrCallKts && !fl._callouts.vr) {
              calloutMsg = 'ROTATE — pitch up (W)';
              calloutColor = '#fbbf24';
              fl._callouts.vr = timeRef.current;
              if (typeof skyAnnounce === 'function') skyAnnounce(__alloT('stem.flightsim.announce_rotate', "Rotate"));
            } else if (!state.onGround && state.vsi > 3 && vAgl > 20 && vAgl < 200 && !fl._callouts.climb) {
              calloutMsg = 'POSITIVE RATE';
              calloutColor = '#22c55e';
              fl._callouts.climb = timeRef.current;
              if (typeof skyAnnounce === 'function') skyAnnounce(__alloT('stem.flightsim.announce_positive_rate', "Positive rate of climb"));
            }
            // Keep the last-triggered callout on screen for 2.2s with fade.
            var lastCall = Math.max(fl._callouts.airspeed, fl._callouts.vr, fl._callouts.climb);
            if (lastCall > 0 && timeRef.current - lastCall < 2.2 && (!state.onGround || groundTakeoffIntent)) {
              var cFade = Math.max(0, 1 - (timeRef.current - lastCall) / 2.2);
              // Re-derive the callout text from which flag most recently fired
              var curMsg, curColor;
              if (fl._callouts.climb === lastCall) { curMsg = 'POSITIVE RATE'; curColor = '#22c55e'; }
              else if (fl._callouts.vr === lastCall) { curMsg = 'ROTATE — pitch up (W)'; curColor = '#fbbf24'; }
              else { curMsg = __alloT('stem.flightsim.hud_airspeed_building', 'AIRSPEED BUILDING'); curColor = '#38bdf8'; }
              gfx.save();
              gfx.globalAlpha = cFade;
              gfx.font = W < 700 ? 'bold 20px system-ui' : 'bold 32px system-ui';
              var cw = Math.min(W - 64, gfx.measureText(curMsg).width + 40);
              var calloutX = Math.max(8, Math.min((W - cw) / 2, W - 56 - cw));
              gfx.fillStyle = 'rgba(2,6,23,0.75)';
              gfx.beginPath(); gfx.roundRect(calloutX, takeoffCalloutY - 28, cw, 54, 8); gfx.fill();
              gfx.strokeStyle = curColor; gfx.lineWidth = 2;
              gfx.beginPath(); gfx.roundRect(calloutX, takeoffCalloutY - 28, cw, 54, 8); gfx.stroke();
              gfx.fillStyle = curColor;
              gfx.textAlign = 'center'; gfx.textBaseline = 'middle';
              gfx.fillText(curMsg, calloutX + cw / 2, takeoffCalloutY, Math.max(1, cw - 40));
              gfx.restore();
              // Suppress calloutMsg local so it doesn't double-render this frame
              calloutMsg = null;
            }
          }

          // ── Flare assist indicator ──
          // When descending through 30 ft AGL with the runway reasonably
          // aligned, paint a green pulsing prompt telling the student to pull
          // back gently. Eases first landings — without it they plant the
          // gear or flare too high.
          if (!heliMode && !droneMode && !state.onGround && !state.stalling && !state.lowAirspeed && nearWp) {
            var faAgl = state.altitude - (nearWp.alt || 0);
            var faVsiFpm = state.vsi * 60;
            if (faAgl < 40 && faAgl > 1 && faVsiFpm < -50 && nearDist < 1 && state.speed > 40) {
              if (runwayApproach && runwayApproach.available && Math.abs(runwayApproach.headingErrorDeg) < 30
                  && Math.abs(runwayApproach.crossFt) <= runwayApproach.runway.widthFt / 2 + 15) {
                var faPulse = 0.6 + Math.sin(timeRef.current * 6) * 0.4;
                var flareText = __alloT('stem.flightsim.hud_flare', "FLARE — ease back on W");
                gfx.save();
                // Keep the compact text plate legible over bright clouds.
                gfx.globalAlpha = instruments.compact ? 1 : faPulse;
                if (instruments.compact) {
                  // A small cue above the attitude indicator keeps its aircraft
                  // symbol and approach needles visible throughout the flare.
                  var faCx = instruments.horizon.x, faCy = Math.min(instruments.horizon.y - instruments.horizon.r - 36, H / 2 - 40);
                  gfx.font = 'bold 10px system-ui';
                  var faW = Math.min(W - 80, gfx.measureText(flareText).width + 20);
                  gfx.fillStyle = 'rgba(6,78,59,0.9)';
                  gfx.beginPath(); gfx.roundRect(faCx - faW / 2, faCy - 12, faW, 24, 5); gfx.fill();
                  gfx.strokeStyle = '#4ade80'; gfx.lineWidth = 1;
                  gfx.beginPath(); gfx.roundRect(faCx - faW / 2, faCy - 12, faW, 24, 5); gfx.stroke();
                  gfx.fillStyle = '#a7f3d0'; gfx.textAlign = 'center'; gfx.textBaseline = 'middle';
                  gfx.fillText(flareText, faCx, faCy, Math.max(1, faW - 16));
                } else {
                  var faCx = instruments.horizon.x, faCy = Math.min(H * 0.72, instruments.horizon.y - instruments.horizon.r - 56);
                  gfx.fillStyle = '#22c55e';
                  gfx.beginPath(); gfx.moveTo(faCx, faCy - 28);
                  gfx.lineTo(faCx - 16, faCy); gfx.lineTo(faCx - 6, faCy);
                  gfx.lineTo(faCx - 6, faCy + 16); gfx.lineTo(faCx + 6, faCy + 16);
                  gfx.lineTo(faCx + 6, faCy); gfx.lineTo(faCx + 16, faCy); gfx.closePath(); gfx.fill();
                  gfx.strokeStyle = '#064e3b'; gfx.lineWidth = 1.5; gfx.stroke();
                  gfx.fillStyle = '#a7f3d0'; gfx.font = 'bold 11px system-ui';
                  gfx.textAlign = 'center'; gfx.textBaseline = 'top';
                  gfx.fillText(flareText, faCx, faCy + 22);
                }
                gfx.restore();
              }
            }
          }

          // ── Radio/radar altimeter callouts during approach to landing ──
          // Descending toward the ground with a runway in reach triggers the
          // classic "Bitchin' Betty" decreasing-altitude callouts — 500, 400,
          // 300, 200, 100, 50, 40, 30, 20, 10, MINIMUMS. One-shot each: once
          // fired, the flag on flightRef.current persists until the plane is
          // back above 600 ft AGL. The voice synthesis is optional (skipped if
          // skyAnnounce is unavailable). On-screen: small HUD pill bottom-right.
